$ErrorActionPreference='Stop';Add-Type -AssemblyName UIAutomationClient,UIAutomationTypes;function Assert-Console{$p=Get-Process -Id 999999 -EA Stop;if($p.Path -ine 'C:\candidate''s folder\iMouse2.exe' -or $p.StartTime.ToUniversalTime().ToFileTimeUtc() -ne 123456789){throw 'console identity changed; no action sent'};if($p.MainWindowHandle -eq 0){throw 'console has no window'};$script:root=[System.Windows.Automation.AutomationElement]::FromHandle($p.MainWindowHandle);if($script:root.Current.ProcessId -ne 999999){throw 'wrong window process'}};Assert-Console;function Find-Id($id){$c=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty,$id);return $script:root.FindFirst([System.Windows.Automation.TreeScope]::Descendants,$c)};$title=Find-Id 'SelectedTitle';if($null -eq $title){throw 'no SelectedTitle'};$name=$title.Current.Name;if($name -notlike '*C24C*' -or $name -like '*C241*'){throw ('selected ' + $name)}; $boxes=$script:root.FindAll([System.Windows.Automation.TreeScope]::Descendants,(New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty,[System.Windows.Automation.ControlType]::CheckBox)));foreach($c in $boxes){$id=[string]$c.Current.AutomationId;$nm=[string]$c.Current.Name;if($id -eq 'BatchMode' -or $id -eq 'SelectAllBox' -or $id -like 'Mirror*' -or $nm -like 'Mirror*'){$tog=[string]$c.GetCurrentPattern([System.Windows.Automation.TogglePattern]::Pattern).Current.ToggleState;if($tog -ne 'Off'){throw ('mirror not Off: '+$id+' '+$nm+' '+$tog)}}};if($null -eq (Find-Id 'SelectAllBox')){throw 'no mirror checkbox'};$hover=Find-Id 'TrackPointer';if($null -eq $hover){throw 'hover state unavailable'};$hoverState=[string]$hover.GetCurrentPattern([System.Windows.Automation.TogglePattern]::Pattern).Current.ToggleState;if($hoverState -ne 'Off'){throw 'hover tracking must be Off'};$connection=Find-Id 'ConnectionStatus';if($null -eq $connection -or $connection.Current.Name -cne 'Connected to iMouse'){throw 'console not connected'};$actual=$null;if(-not [Uri]::TryCreate($connection.Current.HelpText,[UriKind]::Absolute,[ref]$actual)){throw 'active service unavailable'};$expected=[Uri]'http://127.0.0.1:9913';if($actual.Scheme -ne $expected.Scheme -or $actual.Host -ne $expected.Host -or $actual.Port -ne $expected.Port -or $actual.UserInfo -ne '' -or $actual.AbsolutePath -ne '/' -or $actual.Query -ne '' -or $actual.Fragment -ne ''){throw 'active service mismatch'};Assert-Console;$el=Find-Id 'HomeButton';if($null -eq $el -or -not $el.Current.IsEnabled -or $el.Current.IsOffscreen){throw 'button unavailable'};$inv=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();Write-Output $inv;[Console]::Out.Flush();$el.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke();'ok'